// Analista: recebe os negócios do Pipedrive (API) e calcula os números do dia anterior (na segunda, de sexta a domingo) vs. a média dos 7 dias anteriores
const F = {
  data: '79ef76eaf31f801f533e773a786cc9c60c57b97b',      // Data de entrada do lead
  estrelas: 'f203d474df1cb565941e2b4f29d57f96b839aab9',  // Qualificação (estrelas)
  obs: '7056162309bbc072b853fe505d6395a9a0f2e234',       // Observações do SDR
  origem: '349261b3e8060a7857a56bf0cf133be588b4ef18',    // Origem do lead
  reuniao: '25192e0b8f809493d71cb43cb66490659c80f70f',   // Reunião agendada
};
const ORIGENS = { 39: 'LP Cartões', 40: 'Site institucional', 41: 'LP Eventos', 42: 'Indicação' };
const SIM = 43;

// O nó do Pipedrive pode devolver os campos personalizados no topo do objeto (API v1) ou dentro de custom_fields (API v2)
const campo = (d, k) => (d.custom_fields && d.custom_fields[k] !== undefined) ? d.custom_fields[k] : d[k];
const opcao = v => (v && typeof v === 'object') ? Number(v.id ?? v.value) : Number(v);

const leads = $input.all().map(i => i.json).filter(d => campo(d, F.data)).map(d => ({
  dia: String(campo(d, F.data)).slice(0, 10),
  origem: ORIGENS[opcao(campo(d, F.origem))] || 'Sem origem',
  estrelas: Number(campo(d, F.estrelas)),
  perdido: d.status === 'lost',
  motivo: d.lost_reason || '',
  obs: campo(d, F.obs) || '',
  reuniao: opcao(campo(d, F.reuniao)) === SIM,
}));
if (!leads.length) throw new Error('Nenhum negócio com "Data de entrada do lead" veio do Pipedrive.');

// Período analisado: o dia anterior à execução. Na segunda, sexta, sábado e domingo (o agente roda de segunda a sexta).
// Modo de demonstração: com os dados fictícios, que terminam em 02/11/2026, preencha DATA_EXECUCAO. Deixe '' para usar a data de hoje.
const DATA_EXECUCAO = '2026-11-03';
const DIA = 86400000;
const iso = t => new Date(t).toISOString().slice(0, 10);
const agoraBR = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const hoje = DATA_EXECUCAO ? Date.parse(DATA_EXECUCAO + 'T00:00:00Z') : Date.UTC(agoraBR.getFullYear(), agoraBR.getMonth(), agoraBR.getDate());
const ehSegunda = new Date(hoje).getUTCDay() === 1;
const periodo = (ehSegunda ? [3, 2, 1] : [1]).map(n => iso(hoje - n * DIA));   // dias analisados
const inicio = Date.parse(periodo[0] + 'T00:00:00Z');
const base = [7, 6, 5, 4, 3, 2, 1].map(n => iso(inicio - n * DIA));          // 7 dias do calendário antes do período
const doDia = leads.filter(l => periodo.includes(l.dia));
const daBase = leads.filter(l => base.includes(l.dia));
if (!doDia.length) throw new Error(`Nenhum lead entre ${periodo[0]} e ${periodo[periodo.length - 1]}. Nada a analisar.`);
const dataRef = periodo.length === 1 ? periodo[0] : `${periodo[0]} a ${periodo[periodo.length - 1]}`;
const observacaoPeriodo = periodo.length === 1
  ? 'Período de um dia.'
  : `Período de ${periodo.length} dias (sexta a domingo). Os números de leads são o total do período; fim de semana costuma ter menos leads, então não trate a queda de volume do sábado e do domingo como problema.`;

const pct = (a, b) => b ? Math.round((a / b) * 1000) / 10 : 0;
const media = arr => arr.length ? Math.round(arr.reduce((s, x) => s + x, 0) / arr.length * 100) / 100 : 0;

const origens = [...new Set(leads.map(l => l.origem))].sort();
const resumo = origens.map(o => {
  const d = doDia.filter(l => l.origem === o);
  const b = daBase.filter(l => l.origem === o);
  const motivos = {};
  d.filter(l => l.perdido && l.motivo).forEach(l => { motivos[l.motivo] = (motivos[l.motivo] || 0) + 1; });
  return {
    origem: o,
    leads_no_periodo: d.length,
    media_leads_por_dia_periodo: Math.round(d.length / periodo.length * 10) / 10,
    media_leads_por_dia_base: Math.round(b.length / base.length * 10) / 10,
    media_estrelas_dia: media(d.map(l => l.estrelas)),
    media_estrelas_base: media(b.map(l => l.estrelas)),
    pct_perdidos_dia: pct(d.filter(l => l.perdido).length, d.length),
    pct_perdidos_base: pct(b.filter(l => l.perdido).length, b.length),
    reunioes_no_dia: d.filter(l => l.reuniao).length,
    pct_reuniao_dia: pct(d.filter(l => l.reuniao).length, d.length),
    pct_reuniao_base: pct(b.filter(l => l.reuniao).length, b.length),
    motivos_de_perda_no_dia: motivos,
    volume_baixo: d.length < 10,
  };
});

const observacoes = {};
origens.forEach(o => {
  observacoes[o] = doDia.filter(l => l.origem === o && l.perdido && l.obs).map(l => l.obs).slice(0, 25);
});

return [{ json: {
  data_analisada: dataRef,
  dias_no_periodo: periodo.length,
  observacao_periodo: observacaoPeriodo,
  periodo_base: `${base[0]} a ${base[base.length - 1]}`,
  total_leads_no_periodo: doDia.length,
  resumo_por_origem: resumo,
  observacoes_dos_sdrs_em_leads_perdidos: observacoes,
} }];

// Extrai o JSON da resposta do modelo (às vezes vem com ```json ... ```)
const t = $input.first().json.text || '';
const i = t.indexOf('{'), j = t.lastIndexOf('}');
let obj;
try { obj = JSON.parse(t.slice(i, j + 1)); } catch (e) { obj = { erro_ao_ler: true, texto_original: t }; }
return [{ json: obj }];

