// Junta o parecer do Revisor com a mensagem do Redator
const t = $input.first().json.text || '';
const i = t.indexOf('{'), j = t.lastIndexOf('}');
let parecer;
try { parecer = JSON.parse(t.slice(i, j + 1)); } catch (e) { parecer = { aprovado: false, problemas: ['O Revisor não devolveu um JSON válido.'] }; }
return [{ json: {
  aprovado: parecer.aprovado === true,
  problemas: parecer.problemas || [],
  mensagem: $('Redator').first().json.text,
} }];

